function homeSurvivors(r){const players=MP.on?MP.players:{0:{name:MP.name||'You',cos:S.cos}};const out=[];for(const id in players){const nid=+id;if((r.mia||[]).indexOf(nid)>=0||(r.dead||[]).indexOf(nid)>=0)continue;out.push({id:nid,cos:(nid===P.id?S.cos:(players[id].cos||{}))});}return out;}
function playHome(r,next){G.state='home';G.paused=false;document.exitPointerLock();$('hud').classList.remove('on');document.body.style.filter='';Aud.stopAmb();Aud.musicSet(0);voiceLobbyMode();
  const sc=buildHomeScene();const H=G.home={t:0,phase:'drive',r,next,done:false,sc,avs:[],camA:new THREE.Vector3(-6,1.7,14),look:new THREE.Vector3(9,1,30),pl:{x:-1,z:-1.4,yaw:0,pitch:0,bob:0},meds:false,cabOpen:0,fdoor:0,uses:[]};
  showScreen('home');$('home').classList.remove('fps');$('homeSub').className='';$('homeSub').textContent='';$('homeCard').className='';$('homePrompt').className='';$('homePrompt').textContent='';$('fadeTxt').textContent='';$('homeLockHint').style.display='none';
  {const b=Aud.play('amb_home',null,0.3,{loop:true,noVar:true});if(b){Aud.ambNodes.push(b.s,b.g);}}
  Aud.noise(7,0.18,null,{f:140,a:1});Aud.tone(44,7,'sawtooth',0.06,null,{lp:110});
  H.survivors=r.failed?[]:homeSurvivors(r);
  for(let i=0;i<H.survivors.length;i++){const sv=H.survivors[i];const av=Assets.rig('player');applyCosmetics(av.root,sv.cos);enhanceRig(av.root,'player');av.root.visible=false;G.scene.add(av.root);av.play('idle',0);H.avs.push({av,sv,i,walking:false,self:sv.id===P.id});}
  homeSub(r.failed?'The van takes the long way home.':'The van takes the long way home. Nobody talks.');
  H.key=e=>{if(G.state!=='home')return;if(e.code==='Escape'){if(document.pointerLockElement===$('gl'))return;e.preventDefault();homeSkip();}else if(e.code==='KeyE'||e.code==='Enter'||(e.code==='Space'&&H.phase!=='explore')){if(e.repeat)return;e.preventDefault();homeConfirm();}};window.addEventListener('keydown',H.key);
  $('home').onclick=e=>{if(e.target.id==='bHomeSkip')return;homeConfirm();};$('bHomeSkip').onclick=e=>{e.stopPropagation();homeSkip();};}
function homeSub(t){const el=$('homeSub');el.className='';setTimeout(()=>{el.textContent=t;el.className=t?'on':'';},350);}
