function homeEnd(){const H=G.home;if(!H||H.done)return;H.done=true;window.removeEventListener('keydown',H.key);$('home').onclick=null;$('home').classList.remove('fps');$('touchUI').style.display='none';document.exitPointerLock();Aud.stopAmb();$('fadeTxt').textContent='';const next=H.next;G.home=null;for(const a of H.avs)G.scene.remove(a.av.root);next();fade(0);}
