function homeUseTarget(){const H=G.home;if(!H||H.phase!=='explore')return null;const p=H.pl;const fx=Math.sin(p.yaw)*-1,fz=Math.cos(p.yaw)*-1;let best=null,bd=9;
  for(const u of H.uses){if(u.off)continue;const dx=u.x-p.x,dz=u.z-p.z;const d=Math.hypot(dx,dz);if(d>u.r)continue;const dot=(dx*fx+dz*fz)/(d||1);if(d>0.6&&dot<0.35)continue;if(d<bd){bd=d;best=u;}}return best;}
