function internTalk(pid){const lines=['"Oh thank god. Do you have a stapler? No? Okay. Here, take this, I found it in the vending machine."','"I\'ve been down here since Q3. Which Q3? Ha. Good one."','"The elevator goes to a floor called \'B3\'. All of them do. Don\'t."','"They pay me in credits too. I don\'t know what a credit is."'];const s=pick(lines);const bonus=1500;if(pid===P.id)internLine(s,bonus);else sendTo(pid,{t:'ev',k:'intern',s,bonus});}
function internLine(s,bonus){subtitle('☕ '+s);Aud.play(s.indexOf('elevator')>=0?'vo_intern_2':'vo_intern_1',null,1,{noVar:true});toast('☕ The intern hands you '+fmt(bonus)+' cr worth of "misc".');S.credits+=bonus;ach('intern');save();G.mission.internDone=true;if(G.mission.internRig){G.scene.remove(G.mission.internRig.root);G.mission.internRig=null;}}
function updateIntern(){const M=G.mission;if(!M.intern||M.internDone||!M.internRig)return;if(P.k===M.intern.k&&dist2(P.pos.x,P.pos.z,M.intern.x,M.intern.z)<2.2&&held('interact')&&!P._internHeld){P._internHeld=true;if(mpHost())internTalk(P.id);else sendAct({k:'intern'});}if(!held('interact'))P._internHeld=false;M.internRig.mixer.update(1/60);}
