const TUT=[{id:'move',t:'<b>WASD</b> to move, <b>Shift</b> to sprint. Sprinting is loud.',ok:()=>P.distance>6},{id:'crouch',t:'Hold <b>C</b> to crouch. Quiet feet, slow feet.',ok:()=>P.crouch},{id:'flash',t:'<b>F</b> toggles your flashlight. Batteries are not infinite. Some things like light.',ok:()=>!P.flash},{id:'flash2',t:'Turn it back <b>on</b> (F). Darkness is a tool, not a home.',ok:()=>P.flash},{id:'voice',t:'Voice: hold <b>R</b> for radio, talk normally for proximity. Creatures can hear the mic (toggle in settings).',ok:()=>P.radio.on||G.t-G.mission.startT>45},{id:'pickup',t:'Find loot and press <b>E</b> to pick it up. Small stuff goes in pockets.',ok:()=>G.mission.stats.pickups>0},{id:'throw',t:'Hold and release <b>LMB</b> to throw whatever is in your hands. Fragile things break. Try it (not on the loot).',ok:()=>G.mission.stats.thrown>0},{id:'map',t:'Press <b>M</b> for the map. It only shows what you have seen. Click to place markers.',ok:()=>G.tips.map},{id:'ping',t:'Press <b>Q</b> to ping what you are looking at. Teammates see it.',ok:()=>S.stats.pings>0},{id:'van',t:'Drop loot in the back of the van, or walk in with it. Then go find the <b>Odd Toy Rabbit</b> in the basement.',ok:()=>{const o=G.objById.tut_rabbit;return o&&(o.held===P.id);}},{id:'run',t:'…that was the lights. Get back to the van. <b>E</b> on the console to depart.',ok:()=>G.mission.state!=='play'}];
let tutI=0;
function tutorialStart(){tutI=0;G.tips={};$('hint').style.display='block';$('hint').innerHTML=TUT[0].t;/* place the rabbit */const dr=G.map.deepRoom;spawnObj({kind:'item',tpl:6,value:900,x:dr.cx,z:dr.cz,k:dr.k,id:'tut_rabbit'});G.mission.objective={id:'tutorial',text:'Complete orientation',done:false};updateObjHud();}
